		if (callRemote) {
			const agentId = options.agentId?.trim() || this.lastStreamingAgentId(sessionId) || 'root';
			const pending = this.engineFrameSource.postIfHeld(sessionId, {
				kind: 'continueGeneration',
				agentId,
				turnId,
				messageId,
			});
			if (!pending) {
