const LEFTOVER_CACHE_TURN_TEXT = 'leftover-cached-turn';
const LEFTOVER_PENDING_REQUEST_ID = 'p-leftover';
const LEFTOVER_ENGINE_SYNC: SyncChrome = { kind: 'closed', reason: 'leftover-engine-sync' };

/** Host mock that baselines leftover turn + pending on every lease listener (D287–D289). */
class LeftoverProjectionSessionView extends Disposable implements IUniverseAgentSessionView {
	declare readonly _serviceBrand: undefined;
	readonly postCalls: { readonly leaseId: string; readonly msg: ConversationWriteMessage }[] = [];
	private leaseSeq = 0;
	private readonly leaseSessions = new Map<string, string>();
	private readonly emitters = new Map<string, Emitter<IUniverseAgentSessionViewFrameEvent>>();

	constructor(private readonly leftoverSync: SyncChrome = { kind: 'idle' }) {
		super();
	}

	onDynamicDidApplyFrame(leaseId: string) {
		let emitter = this.emitters.get(leaseId);
		if (!emitter) {
			emitter = this._register(new Emitter<IUniverseAgentSessionViewFrameEvent>({
				onDidAddFirstListener: () => {
					queueMicrotask(() => this.emitLeftover(leaseId));
				},
			}));
			this.emitters.set(leaseId, emitter);
		}
		return emitter.event;
	}

	async acquireLease(sessionId: string) {
		const leaseId = `lease:${sessionId}:${++this.leaseSeq}`;
		this.leaseSessions.set(leaseId, sessionId);
		return leaseId;
	}
	async whenEngineSessionReady(sessionId: string) { return sessionId; }
	async releaseLease() { }
	async post(leaseId: string, msg: ConversationWriteMessage) {
		this.postCalls.push({ leaseId, msg });
		return { accepted: true as const, correlation: { id: 'mock' } };
	}
	async requestResync() { }
	async acknowledge() { }
	async requestDetail() { return { ok: false as const, reason: 'unavailable' as const }; }

	private emitLeftover(leaseId: string): void {
		const emitter = this.emitters.get(leaseId);
		if (!emitter) {
			return;
		}
		const sessionId = this.leaseSessions.get(leaseId) ?? (leaseId.startsWith('lease:') ? leaseId.slice('lease:'.length) : leaseId);
		const projection = stubTurnsToSnapshot(sessionId, [
			{ id: 'u-leftover', kind: 'user', text: LEFTOVER_CACHE_TURN_TEXT },
			{ id: LEFTOVER_PENDING_REQUEST_ID, kind: 'confirmation', text: 'leftover-pending', status: 'pending' },
		]);
		emitter.fire({
			leaseId,
			sessionId,
			applied: { kind: 'baseline' },
			frame: {
				frame: {
					leaseId: leaseId as ViewLeaseId,
					generation: 1,
					frameId: 1,
					version: 1,
					body: { kind: 'baseline', snapshot: { ...projection.snapshot, sync: this.leftoverSync } },
				},
				attribution: [...projection.attribution.entries()].map(([itemId, attribution]) => ({
					op: 'upsertAttribution' as const,
					itemId,
					attribution,
				})),
			},
		});
	}
}

/** Host mock that baselines one snapshot on every lease listener. */
class BaselineProjectionSessionView extends Disposable implements IUniverseAgentSessionView {
	declare readonly _serviceBrand: undefined;
	readonly postCalls: { readonly leaseId: string; readonly msg: ConversationWriteMessage }[] = [];
	readonly acknowledgeCalls: { generation: number; frameId: number; appliedVersion: number }[] = [];
	private readonly frameCursors = new Map<string, { generation: number; frameId: number; version: number }>();
	private leaseSeq = 0;
	private readonly leaseSessions = new Map<string, string>();
	private readonly emitters = new Map<string, Emitter<IUniverseAgentSessionViewFrameEvent>>();

	constructor(private readonly snapshotFor: (sessionId: string) => SessionViewSnapshot) {
		super();
	}

	onDynamicDidApplyFrame(leaseId: string) {
		let emitter = this.emitters.get(leaseId);
		if (!emitter) {
			emitter = this._register(new Emitter<IUniverseAgentSessionViewFrameEvent>({
				onDidAddFirstListener: () => {
					queueMicrotask(() => this.emitBaseline(leaseId));
				},
			}));
			this.emitters.set(leaseId, emitter);
		}
		return emitter.event;
	}

	async acquireLease(sessionId: string) {
		const leaseId = `lease:${sessionId}:${++this.leaseSeq}`;
		this.leaseSessions.set(leaseId, sessionId);
		return leaseId;
	}
	async whenEngineSessionReady(sessionId: string) { return sessionId; }
	async releaseLease() { }
	async post(leaseId: string, msg: ConversationWriteMessage) {
		this.postCalls.push({ leaseId, msg });
		return { accepted: true as const, correlation: { id: 'mock' } };
	}
	async requestResync() { }
	async acknowledge(_leaseId: string, ack: { generation: number; frameId: number; appliedVersion: number }) { this.acknowledgeCalls.push(ack); }
	async requestDetail() { return { ok: false as const, reason: 'unavailable' as const }; }

	emitPatches(sessionId: string, patches: readonly ViewPatch[]): void {
		for (const [leaseId, heldSessionId] of this.leaseSessions) {
			const cursor = this.frameCursors.get(leaseId);
			if (heldSessionId !== sessionId || !cursor) { continue; }
			cursor.frameId++;
			cursor.version++;
			this.emitters.get(leaseId)?.fire({
				leaseId, sessionId,
				applied: { kind: 'patches', changedIds: new Set(['sync']) },
				frame: { frame: { leaseId: leaseId as ViewLeaseId, ...cursor, body: { kind: 'patches', patches } } },
			});
		}
	}

	emitGeneration(snapshot: SessionViewSnapshot, generation: number): void {
		for (const [leaseId, sessionId] of this.leaseSessions) {
			if (sessionId !== String(snapshot.sessionId)) { continue; }
			const previous = this.frameCursors.get(leaseId);
			const cursor = { generation, frameId: previous?.generation === generation ? previous.frameId + 1 : 1, version: previous?.generation === generation ? previous.version + 1 : 1 };
			this.frameCursors.set(leaseId, cursor);
			this.emitters.get(leaseId)?.fire({
				leaseId, sessionId, applied: { kind: 'baseline' },
				frame: { frame: { leaseId: leaseId as ViewLeaseId, ...cursor, body: { kind: 'baseline', snapshot } } },
			});
		}
	}

	private emitBaseline(leaseId: string): void {
		const emitter = this.emitters.get(leaseId);
		if (!emitter) {
			return;
		}
		const sessionId = this.leaseSessions.get(leaseId) ?? 'ua-only';
		this.frameCursors.set(leaseId, { generation: 1, frameId: 1, version: 1 });
		emitter.fire({
			leaseId,
			sessionId,
			applied: { kind: 'baseline' },
			frame: {
				frame: {
					leaseId: leaseId as ViewLeaseId,
					generation: 1,
					frameId: 1,
					version: 1,
					body: { kind: 'baseline', snapshot: this.snapshotFor(sessionId) },
				},
			},
		});
	}
}

