	};
	private connected = false;
	private pairingPending = false;
	private explicitPhase: ConnectionPhase | undefined;
	private sessions: { sessionId: string; title?: string; workDir?: string }[] = [];
	private readonly _onDidChangeConnection = new Emitter<UniverseAgentConnectionSnapshot>();
	readonly onDidChangeConnection = this._onDidChangeConnection.event;

	private publishedEngineIdentityId: string | undefined;
	private publishedLinkId: number | undefined;

	getQueue?: IUniverseAgentConnection['getQueue'];
	readonly getQueueCalls: string[] = [];
	enableQueueReadback(fetch?: (id: string) => Promise<UniverseAgentQueueState>): void {
		this.publishedEngineIdentityId = 'queue-engine'; this.publishedLinkId = 1;
		this.getQueue = async request => {
			this.getQueueCalls.push(request.sessionId);
			return fetch ? fetch(request.sessionId) : { items: [], isPaused: false, isProcessing: false, pauseReason: 'NONE', version: '0' };
		};
	}

	setConnected(value: boolean): void {
		this.connected = value;
		if (value) {
			this.explicitPhase = undefined;
		}
		this._onDidChangeConnection.fire(this.getConnectionSnapshot());
	}

	/** One snapshot: identity, link id, and connected flag change together. */
	setPublishedLink(engineIdentityId: string | undefined, linkId: number | undefined, connected: boolean): void {
		this.publishedEngineIdentityId = engineIdentityId && engineIdentityId.length > 0 ? engineIdentityId : undefined;
		this.publishedLinkId = typeof linkId === 'number' && linkId > 0 ? linkId : undefined;
		this.connected = connected;
		this._onDidChangeConnection.fire(this.getConnectionSnapshot());
	}

	setPairingPending(value: boolean): void {
		this.pairingPending = value;
		if (!value) {
			this.explicitPhase = undefined;
		}
		this._onDidChangeConnection.fire(this.getConnectionSnapshot());
	}

	/** Production pairing snapshot: connecting phase + pairingPending, not engine-connected. */
	setPairingConnectingPhase(reason: 'initial' | 'transport_lost' = 'initial'): void {
		this.pairingPending = true;
		this.connected = false;
		this.explicitPhase = { kind: 'connecting', reason };
		this._onDidChangeConnection.fire(this.getConnectionSnapshot());
	}

	setListSessions(sessions: { sessionId: string; title?: string; workDir?: string }[]): void {
		this.sessions = sessions;
	}

	isEngineConnected(): boolean {
		return this.connected && !this.pairingPending;
	}

	getTransportState() { return 'ok' as const; }
	getConnectionPhase() {
		if (this.explicitPhase) {
			return this.explicitPhase;
		}
		return this.connected
			? { kind: 'connected' as const, path: 'loopback' as const }
			: { kind: 'disconnected' as const };
	}
	getConnectionSnapshot(): UniverseAgentConnectionSnapshot {
		return {
			transport: 'ok',
			authenticated: this.connected,
			pairingPending: this.pairingPending,
			channelAlive: this.connected,
			sharedFsRootSent: false,
			capabilities: {} as UniverseAgentConnectionSnapshot['capabilities'],
			...(this.getQueue ? { conversationEntryCapability: { ...createUnknownConversationEntryCapability(), getQueue: 'SUPPORTED' as const } } : {}),
			...(this.publishedEngineIdentityId ? { engineIdentityId: this.publishedEngineIdentityId } : {}),
			...(this.publishedLinkId !== undefined ? { linkId: this.publishedLinkId } : {}),
		};
	}
	getCapabilitySnapshot() { return this.getConnectionSnapshot().capabilities; }
	requestAgentTreeRefresh(sessionId?: string) {
		this.treeRefreshCalls.push(sessionId ?? '');
	}
	getNavigatorCapability() { return 'UNKNOWN' as const; }
	isAgentTreeFetchFailed() { return false; }
	async connect() { return { methods: [], events: [], sessionToken: 'tok' }; }
	async connectProfile() { return { ok: false as const, code: 'transport_failed' as const, reason: 'stub' }; }
	async confirmPairing() { return { ok: false as const, code: 'transport_failed' as const, reason: 'stub' }; }
	async cancelPairing() { }
	async probeConnectionProfile() { return { ok: false as const, code: 'transport_failed' as const, reason: 'stub' }; }
	async disconnect() { this.setConnected(false); }
	readonly listSessionsCalls: Record<string, never>[] = [];
	async listSessions() {
		this.listSessionsCalls.push({});
		if (this.listSessionsError) {
			throw this.listSessionsError;
		}
		return {
			sessions: this.sessions.map(s => ({
				sessionId: s.sessionId,
				title: s.title,
				...(s.workDir ? { workDir: s.workDir } : {}),
			})),
		};
	}
	readonly renameCalls: { sessionId: string; title: string }[] = [];
	readonly createCalls: { title?: string; clientSessionId?: string }[] = [];
	createSessionResult: { sessionId: string } = { sessionId: 'ua-new' };
	createSessionError: Error | undefined;
	listSessionsError: Error | undefined;
	readonly treeRefreshCalls: string[] = [];
	async createSession(request: { title?: string; clientSessionId?: string }) {
		this.createCalls.push({ title: request.title, clientSessionId: request.clientSessionId });
		if (this.createSessionError) {
			throw this.createSessionError;
		}
		return this.createSessionResult;
	}
	deleteError: Error | undefined;
	/** When set, `deleteSession` waits here before resolving or throwing. */
	deleteSessionGate: Promise<void> | undefined;
	readonly deleteCalls: { sessionId: string }[] = [];
	async deleteSession(request: { sessionId: string }) {
		this.deleteCalls.push({ sessionId: request.sessionId });
		if (this.deleteSessionGate) {
			await this.deleteSessionGate;
		}
		if (this.deleteError) {
			throw this.deleteError;
		}
	}
	renameResult: { ok: boolean; message?: string } = { ok: true };
	renameError: Error | undefined;
	async renameSession(request: { sessionId: string; title: string }) {
		this.renameCalls.push({ sessionId: request.sessionId, title: request.title });
		if (this.renameError) {
			throw this.renameError;
		}
		return this.renameResult;
	}
	readonly cancelCalls: { sessionId: string; agentId: string }[] = [];
	writeResult: { ok: boolean; error?: string; message?: string } = { ok: true };
	writeError: Error | undefined;
	private async resolveWriteResult<T extends { ok: boolean }>(success: T): Promise<T | { ok: boolean; error?: string; message?: string }> {
		if (this.writeError) {
			throw this.writeError;
		}
		if (this.writeResult.ok === false) {
			return this.writeResult;
		}
		return success;
	}
	async cancelGeneration(request: { sessionId: string; agentId: string }) {
		this.cancelCalls.push({ sessionId: request.sessionId, agentId: request.agentId });
		return this.resolveWriteResult({ ok: true });
	}
