	return {
		sessionId: sessionId as SessionId,
		sync: { kind: 'idle' },
		timeline: [allow.item, deny.item],
		overlay: { blocks: [] },
		pendingActions: [allow.pending, deny.pending],
		localPendingSends: [],
	};
}

